using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.AI.Evaluation.Reporting.Storage;
using OpenTelemetry;
using OpenTelemetry.Resources;
using OpenTelemetry.Trace;

namespace MyApp.Evals;

internal static class EvalConfiguration
{
    private static readonly string ResultsPath =
        Path.Combine(Path.GetTempPath(), "MyApp.Evals", "results");

    /// <summary>
    /// Creates a reporting configuration that stores results on disk and
    /// configures the evaluators for the requested mode.
    /// </summary>
    public static ReportingConfiguration CreateForQuality(IChatClient judge)
    {
        var storage = new DiskBasedReportingStorage(ResultsPath);

        var evaluators = new IEvaluator[]
        {
            new RelevanceEvaluator(),
            new CoherenceEvaluator(),
            new FluencyEvaluator(),
            new GroundednessEvaluator(),
        };

        return new ReportingConfiguration(storage, evaluators, chatClient: judge);
    }

    /// <summary>
    /// Creates a reporting configuration for compare mode that runs two
    /// scenarios side by side and persists both result sets for diffing.
    /// </summary>
    public static ReportingConfiguration CreateForCompare(IChatClient judge, string scenarioTag)
    {
        var storage = new DiskBasedReportingStorage(
            Path.Combine(ResultsPath, "compare", scenarioTag));

        var evaluators = new IEvaluator[]
        {
            new RelevanceEvaluator(),
            new CoherenceEvaluator(),
        };

        return new ReportingConfiguration(storage, evaluators, chatClient: judge);
    }

    /// <summary>
    /// Configures OpenTelemetry tracing for the eval run so LLM calls are
    /// captured to the console (telemetry mode).
    /// </summary>
    public static TracerProvider BuildTelemetryProvider()
    {
        return Sdk.CreateTracerProviderBuilder()
            .SetResourceBuilder(ResourceBuilder.CreateDefault().AddService("MyApp.Evals"))
            .AddSource("Microsoft.Extensions.AI")
            .AddSource("Azure.*")
            .AddHttpClientInstrumentation()
            .AddConsoleExporter()
            .Build()!;
    }
}

using Microsoft.Extensions.AI;
using Microsoft.VisualStudio.TestTools.UnitTesting;
using OpenTelemetry.Trace;

namespace MyApp.Evals;

/// <summary>
/// Telemetry mode: runs the agent and asserts that OTel traces are emitted
/// for each LLM interaction.
/// </summary>
[TestClass]
public class TelemetryTests
{
    [TestMethod]
    public async Task Agent_EmitsTraces_ForLlmCalls()
    {
        using var tracerProvider = EvalConfiguration.BuildTelemetryProvider();

        // Build a simple in-process chat client for testing
        var builder = new ChatClientBuilder()
            .UseFunctionInvocation()
            .UseOpenTelemetry(configure: o => o.EnableSensitiveData = true);

        // Use a test model endpoint (configure via env var or test settings)
        var endpoint = Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
