using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evals;

/// <summary>
/// Quality mode: evaluates agent responses using LLM-as-judge scoring
/// for relevance, coherence, fluency, and groundedness.
/// </summary>
[TestClass]
public class QualityTests
{
    private static readonly string[] Scenarios =
    [
        "What is the best way to structure a .NET solution?",
        "Explain dependency injection in three sentences.",
        "How do I add logging to an ASP.NET Core app?",
    ];

    [TestMethod]
    [DynamicData(nameof(GetScenarios), DynamicDataSourceType.Method)]
    public async Task Agent_ResponseQuality_MeetsThreshold(string prompt)
    {
        // Arrange: set up judge and reporting
        var judgeEndpoint = Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
            ?? throw new InvalidOperationException("Set AZURE_OPENAI_ENDPOINT to run quality evals.");
        var judgeKey = Environment.GetEnvironmentVariable("AZURE_OPENAI_KEY")
            ?? throw new InvalidOperationException("Set AZURE_OPENAI_KEY to run quality evals.");

        IChatClient judge = new Azure.AI.OpenAI.AzureOpenAIClient(
            new Uri(judgeEndpoint),
            new System.ClientModel.ApiKeyCredential(judgeKey))
            .GetChatClient("gpt-4o-mini")
            .AsIChatClient();

        var config = EvalConfiguration.CreateForQuality(judge);

        await using var scenario = await config.CreateScenarioRunAsync(
            scenarioName: prompt[..Math.Min(40, prompt.Length)]);

        // Act: get agent response
        var messages = new List<ChatMessage> { new(ChatRole.User, prompt) };
        var response = await judge.GetResponseAsync(messages);

        // Evaluate
        await scenario.EvaluateAsync(messages, response);

        // Assert: all scores above threshold
        foreach (var result in scenario.GetResults())
        {
            if (result is NumericMetric numeric)
            {
                Assert.IsTrue(
                    numeric.Value >= 3.0,
                    $"{numeric.Name} scored {numeric.Value}, expected >= 3.0");
            }
        }
    }

    private static IEnumerable<object[]> GetScenarios()
        => Scenarios.Select(s => new object[] { s });
}

