        await using var scenarioB = await configB.CreateScenarioRunAsync(scenarioName: "compare-full");
        await scenarioB.EvaluateAsync(messages, responseB);

        // Both should produce valid results
        Assert.IsTrue(scenarioA.GetResults().Any(), "Model A should produce eval results");
        Assert.IsTrue(scenarioB.GetResults().Any(), "Model B should produce eval results");
    }
}

